//! Process-level ownership and acknowledgement boundaries, using synthetic DEV profiles only.
use std::{fs,io::{BufRead,BufReader,Write},path::PathBuf,process::{Child,Command,Stdio},sync::Arc,time::{Duration,Instant}};
use std::os::windows::process::CommandExt;
use floatboard_agent::storage::Database;
use floatboard_client::{Client,Profile,files::atomic_json};
use floatboard_protocol::{Request,Response};
use serde_json::{json,Value};
struct Fixture{profile:Profile,path:PathBuf}
impl Fixture{
 fn new()->Self{let root=floatboard_client::windows::local_home().unwrap().join("CodexFloatboard-Dev/process-tests").join(uuid::Uuid::new_v4().to_string());fs::create_dir_all(root.join("codex")).unwrap();let listener=std::net::TcpListener::bind("127.0.0.1:0").unwrap();let port=listener.local_addr().unwrap().port();drop(listener);let profile=Profile{profile_id:uuid::Uuid::new_v4().to_string(),owner_sid:floatboard_client::windows::sid().unwrap(),environment:"development".into(),root:root.clone(),port,agent_exe:PathBuf::from(env!("CARGO_BIN_EXE_FloatboardAgent")),gui_exe:root.join("CodexFloatboard.exe"),codex_home:root.join("codex")};let path=root.join("registration.json");atomic_json(&path,&json!(profile)).unwrap();let db=Database::initialize(profile.clone()).unwrap();floatboard_agent::storage::put(&db.store.db,"write_gate",&json!("open")).unwrap();drop(db);Self{profile,path}}
 fn spawn(&self)->Child{Command::new(&self.profile.agent_exe).args(["--profile"]).arg(&self.path).stdin(Stdio::null()).stdout(Stdio::null()).stderr(Stdio::null()).creation_flags(0x08000000).spawn().unwrap()}
 fn start(&self)->Running{let child=self.spawn();let mut running=Running{child,client:Client::new(self.profile.clone())};let until=Instant::now()+Duration::from_secs(15);loop{if running.client.call("identity",json!({})).is_ok(){return running;}assert!(running.child.try_wait().unwrap().is_none(),"Agent exited before readiness");assert!(Instant::now()<until,"readiness timeout");std::thread::sleep(Duration::from_millis(30));}}
}
impl Drop for Fixture{fn drop(&mut self){let _=fs::remove_dir_all(&self.profile.root);}}
struct Running{child:Child,client:Client}
impl Running{fn stop(&mut self){self.client.call("stop",json!({"confirmed":true})).unwrap();let until=Instant::now()+Duration::from_secs(10);while self.child.try_wait().unwrap().is_none(){assert!(Instant::now()<until,"normal shutdown timed out");std::thread::sleep(Duration::from_millis(20));}}}
impl Drop for Running{fn drop(&mut self){if self.child.try_wait().ok().flatten().is_none(){let _=self.client.call("stop",json!({"confirmed":true}));let until=Instant::now()+Duration::from_secs(5);while self.child.try_wait().ok().flatten().is_none()&&Instant::now()<until{std::thread::sleep(Duration::from_millis(20));}if self.child.try_wait().ok().flatten().is_none(){let _=self.child.kill();let _=self.child.wait();}}}}
fn report(client:&Client,id:&str)->Value{let hook=client.call("hook_context",json!({"hook_event_name":"SessionStart","session_id":id,"cwd":"D:/synthetic"})).unwrap();let context=hook["hookSpecificOutput"]["additionalContext"].as_str().unwrap();let token=context.split("session_token=").nth(1).unwrap().split(';').next().unwrap();json!({"session_id":id,"session_token":token,"revision":1,"title":"synthetic process task","status":"running","plan":[{"id":"one","title":"work","status":"inProgress"}],"blockers":[],"evidence":[]})}
fn raw(profile:&Profile,request:&Request)->Response{let mut file=fs::OpenOptions::new().read(true).write(true).open(profile.pipe()).unwrap();let mut bytes=serde_json::to_vec(request).unwrap();bytes.push(b'\n');file.write_all(&bytes).unwrap();let mut line=String::new();BufReader::new(file).read_line(&mut line).unwrap();serde_json::from_str(&line).unwrap()}

#[test]fn background_agent_never_requires_a_console(){let bytes=fs::read(env!("CARGO_BIN_EXE_FloatboardAgent")).unwrap();assert_eq!(&bytes[..2],b"MZ");let pe=u32::from_le_bytes(bytes[0x3c..0x40].try_into().unwrap()) as usize;assert_eq!(&bytes[pe..pe+4],b"PE\0\0");let subsystem=pe+24+68;assert_eq!(u16::from_le_bytes(bytes[subsystem..subsystem+2].try_into().unwrap()),2,"scheduled Agent must use the Windows subsystem in every build");}

#[test]fn one_ten_and_hundred_sessions_share_one_committing_owner(){let f=Fixture::new();let mut agent=f.start();let first=agent.client.call("identity",json!({})).unwrap();for count in [1,10,100]{let client=Arc::new(agent.client.clone());let workers=(0..count).map(|i|{let client=client.clone();std::thread::spawn(move||{let value=report(&client,&format!("session-{count}-{i}"));let receipt=client.call("report_progress",value.clone()).unwrap();assert_eq!(receipt["accepted"],true);assert_eq!(client.call("report_progress",value).unwrap(),receipt);client.call("identity",json!({})).unwrap()})}).collect::<Vec<_>>();for worker in workers{let identity=worker.join().unwrap();assert_eq!(identity["agent_instance_id"],first["agent_instance_id"]);assert_eq!(identity["database_instance_id"],first["database_instance_id"]);}}
 for _ in 0..100{assert_eq!(agent.client.call("identity",json!({})).unwrap()["agent_instance_id"],first["agent_instance_id"]);}
 agent.stop();let db=Database::open(f.profile.clone()).unwrap();assert_eq!(db.store.db.query_row::<i64,_,_>("select count(*) from report_receipts",[],|r|r.get(0)).unwrap(),111);assert_eq!(db.store.db.query_row::<String,_,_>("pragma integrity_check",[],|r|r.get(0)).unwrap(),"ok");
}
#[test]fn concurrent_starts_and_same_uuid_different_root_cannot_split_ownership(){let f=Fixture::new();let mut children=(0..10).map(|_|f.spawn()).collect::<Vec<_>>();let client=Client::new(f.profile.clone());let until=Instant::now()+Duration::from_secs(15);while client.call("identity",json!({})).is_err(){assert!(Instant::now()<until);std::thread::sleep(Duration::from_millis(30));}let until=Instant::now()+Duration::from_secs(10);loop{let count=children.iter_mut().map(|child|child.try_wait().unwrap().is_none()).filter(|alive|*alive).count();if count==1{break;}assert!(Instant::now()<until,"more than one owner alive");std::thread::sleep(Duration::from_millis(30));}
 let mut other=f.profile.clone();other.root=f.profile.root.join("different");fs::create_dir_all(&other.root).unwrap();let config=other.root.join("profile.json");atomic_json(&config,&json!(other)).unwrap();assert!(!Command::new(&other.agent_exe).arg("--profile").arg(config).creation_flags(0x08000000).output().unwrap().status.success());assert!(!other.root.join("events.sqlite3").exists());client.call("stop",json!({"confirmed":true})).unwrap();for mut child in children{child.wait().unwrap();}}
#[test]fn response_loss_and_abrupt_restart_preserve_only_committed_receipts(){let f=Fixture::new();let mut agent=f.start();let value=report(&agent.client,"crash-test");let receipt=agent.client.call("report_progress",value.clone()).unwrap();let request=Request{protocol:2,profile_id:f.profile.profile_id.clone(),request_id:"lost-setting-response".into(),method:"preferences".into(),params:json!({"theme":"light","settings_revision":0})};
 {let mut pipe=fs::OpenOptions::new().read(true).write(true).open(f.profile.pipe()).unwrap();let mut bytes=serde_json::to_vec(&request).unwrap();bytes.push(b'\n');pipe.write_all(&bytes).unwrap();}
 let until=Instant::now()+Duration::from_secs(5);loop{let result=agent.client.call("request_result",json!({"request_id":request.request_id})).unwrap();if result["committed"]==true{break;}assert!(Instant::now()<until);std::thread::sleep(Duration::from_millis(20));}
 agent.child.kill().unwrap();agent.child.wait().unwrap();drop(agent);let mut agent=f.start();assert_eq!(agent.client.call("report_progress",value).unwrap(),receipt);assert_eq!(agent.client.call_id("preferences",request.params,&request.request_id).unwrap()["settings_revision"],1);agent.stop();}
#[test]fn endpoint_profile_protocol_and_live_file_replacement_are_rejected(){let f=Fixture::new();let mut agent=f.start();let mut request=Request{protocol:999,profile_id:f.profile.profile_id.clone(),request_id:"bad".into(),method:"identity".into(),params:json!({})};assert!(raw(&f.profile,&request).error.is_some());request.protocol=2;request.profile_id=uuid::Uuid::new_v4().to_string();assert!(raw(&f.profile,&request).error.is_some());assert!(fs::rename(f.profile.root.join("events.sqlite3"),f.profile.root.join("replaced.sqlite3")).is_err());assert_eq!(agent.client.call("identity",json!({})).unwrap()["storage"]["status"],"ok");agent.stop();let listener=std::net::TcpListener::bind(("127.0.0.1",f.profile.port)).unwrap();let mut child=f.spawn();let until=Instant::now()+Duration::from_secs(10);while child.try_wait().unwrap().is_none(){assert!(Instant::now()<until);std::thread::sleep(Duration::from_millis(20));}assert!(!child.wait().unwrap().success());drop(listener);}
